#include "4aed32c9e5f5f96e_item_equip_restrictions.hpp"
namespace recovered_item_equip_restrictions{
static U element(U item,U i,Ports&p){return static_cast<std::int32_t>(i)>=0&&static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(item+0x24c))?p.read(item+0x254)+28*i:0;}
static bool active(U item,U i,Ports&p){U upgrade=p.byte(element(item,i,p)+17);return upgrade==255||(p.read(item+0x294)&(1u<<(upgrade&31)));}
U alignment(U self,U item,Ports&p){if(!p.has(item,43,0)||p.feat(p.read(self+0xa74),93))return 1;auto value=static_cast<std::int16_t>(p.half(p.read(self+0xa74)+0x17e));U alignment=value<=40?3:value>=60?2:1;for(U i=0;static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(item+0x24c));++i)if(active(item,i,p)&&p.half(element(item,i,p))==43&&p.half(element(item,i,p)+2)!=alignment)return 0;return 1;}
U classes(U self,U item,Ports&p){if(!p.has(item,44,0)||p.feat(p.read(self+0xa74),93))return 1;for(U i=0;static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(item+0x24c));++i)if(active(item,i,p)&&p.half(element(item,i,p))==44){U property=element(item,i,p);U stats=p.read(self+0xa74);U required=p.half(property+2);U count=p.byte(stats+0x89);for(U c=0;c<count;){if(required==(p.class_id(stats,c)&255))return 1;stats=p.read(self+0xa74);count=p.byte(stats+0x89);++c;}}return 0;}
U race(U self,U item,Ports&p){bool restricted=true;if(p.has(item,10,0)&&p.find(item,10,129))restricted=false;U rule=p.rule(item);U restriction=p.byte(rule+0xb4);if(restriction&&restricted){if(restriction==2){if(p.half(p.read(self+0xa74)+0xdc)!=5)return 0;}else if(restriction==1){if(p.half(p.read(self+0xa74)+0xdc)!=6)return 0;}else return 0;}
 U gender=p.byte(p.read(self+0xa74)+0xe8);rule=p.rule(item);if(p.read(rule+0xb8)&(1u<<(gender&31)))return 0;
 if(!p.has(item,45,0)){return 1;}for(U i=0;static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(item+0x24c));++i)if(active(item,i,p)&&p.half(element(item,i,p))==45){(void)element(item,i,p);U creatureRace=p.half(p.read(self+0xa74)+0xdc);if(creatureRace==p.half(element(item,i,p)+2))return 1;}return 0;}
U feats(U self,U item,Ports&p){if(!p.has(item,57,0)||p.feat(p.read(self+0xa74),93))return 1;for(U i=0;static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(item+0x24c));++i)if(active(item,i,p)&&p.half(element(item,i,p))==57){U required=p.half(element(item,i,p)+2);if(!(p.feat_uses(p.read(self+0xa74),required)&255))return 0;}return 1;}
}
